std::complex<double> DT::A1A1HHTree(const double &cos_t, const double &s)
{
    std::complex<double> MHSqcomp = std::complex<double>(MH*MH,-MH*WH);
    std::complex<double> MS1Sqcomp = std::complex<double>(MS1*MS1,-MS1*WS1);
    
    double t =  ((MA1*MA1) + (-s + cos_t*sqrt(s - 4.* (MA1*MA1))*sqrt(s - 4.* (MHSqcomp.real())))/2. +  (MHSqcomp.real()));
	double u = -s - t + MA1*MA1 + MA1*MA1 + MHSqcomp.real() + MHSqcomp.real();

    return (4.*(MHSqcomp*MHSqcomp)*(1/(-t + (MA1*MA1)) + 1/(-u + (MA1*MA1)))*(sin(alpha)*sin(alpha)) + (4.*(MHSqcomp)*(s + 2.*(MHSqcomp))*(sin(alpha)*sin(alpha)*sin(alpha)*sin(alpha)))/(-s + (MHSqcomp)) + ((s + 2.*(MHSqcomp))*(MS1Sqcomp)*(sin(2*alpha)*sin(2*alpha)))/(-s + (MS1Sqcomp)) + (4.*s*svev*(s + 2.*(MHSqcomp))*((MHSqcomp) - (MS1Sqcomp))*(cos(alpha)*cos(alpha)*cos(alpha))*sin(alpha))/(vev*(-s + (MHSqcomp))*(s - (MS1Sqcomp))))/(4.*(svev*svev));
}


inline std::complex<double>
operator+(int lhs, const std::complex<double>& rhs)
{
    return std::complex<double>(static_cast<double>(lhs), 0.0) + rhs;
}
   template <typename T>
std::complex<T> operator*(int lhs, const std::complex<T>& rhs) {
   return static_cast<T>(lhs) * rhs;
}

inline double Csc(double x) {
return 1.0 / sin(x);
}

inline double Sec(double x) {
return 1.0 / cos(x);
}

inline double Cot(double x) {
return std::tan(M_PI_2 - x);
}
