    std::complex<double> MH2c = sqrt(MS1*MS1 + std::complex<double>(0,MS1*WS1));
    double t = (MA1*MA1) + (-s + cos_t*sqrt(s - 4.*(MA1*MA1))*sqrt(s - 4.*(MH*MH)))/2. + (MH*MH);
